     1→"use client";
     2→
     3→import { logger } from "@/lib/logger";
     4→import type { ErrorInfo, ReactNode } from "react";
     5→import { Component } from "react";
     6→import { Button } from "../ui/button";
     7→import {
     8→  Card,
     9→  CardDescription,
    10→  CardFooter,
    11→  CardHeader,
    12→  CardTitle,
    13→} from "../ui/card";
    14→
    15→type Props = {
    16→  children?: ReactNode;
    17→  fallback?: ReactNode | ((error: string) => ReactNode);
    18→  title?: string;
    19→  description?: string;
    20→};
    21→
    22→type State = {
    23→  hasError: boolean;
    24→  error: string;
    25→};
    26→
    27→/**
    28→ * ErrorBoundary is a component that catches errors in its children and renders a fallback UI.
    29→ * It's useful for handling errors in the UI and preventing the entire app from crashing.
    30→ * It use class component because it uses componentDidCatch lifecycle method.
    31→ */
    32→export class ErrorBoundary extends Component<Props, State> {
    33→  public state: State = {
    34→    hasError: false,
    35→    error: "",
    36→  };
    37→
    38→  public static getDerivedStateFromError(error: Error): State {
    39→    // Update state so the next render will show the fallback UI.
    40→    logger.error("ErrorBoundary: ", error.message);
    41→    return { hasError: true, error: error.message };
    42→  }
    43→
    44→  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    45→    logger.error("Uncaught error:", error, errorInfo);
    46→  }
    47→
    48→  public async render() {
    49→    if (!this.state.hasError) {
    50→      return this.props.children;
    51→    }
    52→
    53→    if (this.props.fallback) {
    54→      if (typeof this.props.fallback === "function")
    55→        return this.props.fallback(this.state.error);
    56→
    57→      return this.props.fallback;
    58→    }
    59→
    60→    const {
    61→      title = "Something went wrong",
    62→      description = "Please try again later",
    63→    } = this.props;
    64→
    65→    return (
    66→      <Card>
    67→        <CardHeader>
    68→          <CardTitle>{title}</CardTitle>
    69→          <CardDescription>{description}</CardDescription>
    70→        </CardHeader>
    71→        <CardFooter>
    72→          <Button
    73→            variant="outline"
    74→            onClick={() => {
    75→              this.setState({ hasError: false });
    76→            }}
    77→          >
    78→            Retry
    79→          </Button>
    80→        </CardFooter>
    81→      </Card>
    82→    );
    83→  }
    84→}
    85→

