     1→import { Card, CardContent } from "@/components/ui/card";
     2→import { Badge } from "@/components/ui/badge";
     3→import { Button } from "@/components/ui/button";
     4→import { Heart, MapPin, Bed, Square, Calendar, TrendingUp } from "lucide-react";
     5→import { cn } from "@/lib/utils";
     6→import type { Property } from "@/lib/moteurimmo/types";
     7→
     8→type PropertyCardB2CProps = {
     9→  property: Property;
    10→  isFavorite?: boolean;
    11→  onToggleFavorite?: (propertyId: string) => void;
    12→  className?: string;
    13→};
    14→
    15→/**
    16→ * B2C Property Card - Emotion-focused design for individual buyers
    17→ * Features: Large images, heart interactions, lifestyle focus, warm colors
    18→ */
    19→export function PropertyCardB2C({
    20→  property,
    21→  isFavorite = false,
    22→  onToggleFavorite,
    23→  className,
    24→}: PropertyCardB2CProps) {
    25→  const formatPrice = (price: number) => {
    26→    return new Intl.NumberFormat("fr-FR", {
    27→      style: "currency",
    28→      currency: "EUR",
    29→      minimumFractionDigits: 0,
    30→      maximumFractionDigits: 0,
    31→    }).format(price);
    32→  };
    33→
    34→  const formatSurface = (surface: number) => {
    35→    return `${surface} m²`;
    36→  };
    37→
    38→  const getTypeLabel = (type: string) => {
    39→    return type === "sale" ? "Vente" : "Location";
    40→  };
    41→
    42→  const getCategoryLabel = (category: string) => {
    43→    switch (category) {
    44→      case "apartment":
    45→        return "Appartement";
    46→      case "house":
    47→        return "Maison";
    48→      case "commercial":
    49→        return "Commercial";
    50→      default:
    51→        return category;
    52→    }
    53→  };
    54→
    55→  return (
    56→    <Card
    57→      className={cn(
    58→        "group overflow-hidden transition-all duration-300 hover:scale-[1.02] hover:shadow-xl",
    59→        "theme-b2c:border-orange-200 theme-b2c:hover:border-orange-300",
    60→        className,
    61→      )}
    62→    >
    63→      {/* Image Container */}
    64→      <div className="relative aspect-[4/3] overflow-hidden">
    65→        {/* Placeholder for property image */}
    66→        <div className="theme-b2c:from-blue-50 theme-b2c:to-orange-50 absolute inset-0 bg-gradient-to-br from-blue-100 to-orange-100" />
    67→
    68→        {/* Property Type Badge */}
    69→        <div className="absolute top-3 left-3">
    70→          <Badge
    71→            variant="secondary"
    72→            className="theme-b2c:bg-orange-50 theme-b2c:text-orange-800 theme-b2c:border-orange-200 bg-white/90 text-gray-800"
    73→          >
    74→            {getTypeLabel(property.type)}
    75→          </Badge>
    76→        </div>
    77→
    78→        {/* Favorite Button */}
    79→        <Button
    80→          variant="ghost"
    81→          size="icon"
    82→          className={cn(
    83→            "absolute top-3 right-3 bg-white/90 backdrop-blur-sm hover:bg-white",
    84→            "transition-all duration-200 hover:scale-110",
    85→            isFavorite && "text-red-500",
    86→          )}
    87→          onClick={() => onToggleFavorite?.(property.id)}
    88→        >
    89→          <Heart
    90→            className={cn(
    91→              "h-5 w-5 transition-all duration-200",
    92→              isFavorite ? "fill-current text-red-500" : "text-gray-600",
    93→            )}
    94→          />
    95→        </Button>
    96→
    97→        {/* Price Overlay */}
    98→        <div className="absolute bottom-3 left-3">
    99→          <div className="theme-b2c:bg-orange-50/95 rounded-lg bg-white/95 px-3 py-1.5 backdrop-blur-sm">
   100→            <p className="theme-b2c:text-orange-900 text-lg font-bold text-gray-900">
   101→              {formatPrice(property.price)}
   102→            </p>
   103→            {property.surface && (
   104→              <p className="theme-b2c:text-orange-700 text-sm text-gray-600">
   105→                {Math.round(property.price / property.surface)} €/m²
   106→              </p>
   107→            )}
   108→          </div>
   109→        </div>
   110→      </div>
   111→
   112→      <CardContent className="p-5">
   113→        {/* Title and Location */}
   114→        <div className="mb-3">
   115→          <h3 className="theme-b2c:text-blue-900 mb-1 line-clamp-2 text-lg font-semibold">
   116→            {property.title}
   117→          </h3>
   118→          <div className="theme-b2c:text-blue-700 flex items-center text-gray-600">
   119→            <MapPin className="mr-1 h-4 w-4 flex-shrink-0" />
   120→            <span className="truncate text-sm">
   121→              {property.city}
   122→              {property.postalCode && `, ${property.postalCode}`}
   123→            </span>
   124→          </div>
   125→        </div>
   126→
   127→        {/* Property Details */}
   128→        <div className="theme-b2c:text-blue-700 mb-4 flex items-center gap-4 text-sm text-gray-600">
   129→          <div className="flex items-center gap-1">
   130→            <Square className="h-4 w-4" />
   131→            <span>{formatSurface(property.surface ?? 0)}</span>
   132→          </div>
   133→          {property.rooms && (
   134→            <div className="flex items-center gap-1">
   135→              <Bed className="h-4 w-4" />
   136→              <span>{property.rooms} pièces</span>
   137→            </div>
